(async () => {
  const { existsSync, mkdirSync } = await import('node:fs');
  const path = await import('node:path');
  const src = process.env.SOURCE_DIR;
  const out = process.env.OUTPUT_DIR;
  if (!src) throw new Error('Missing SOURCE_DIR');
  if (!out) throw new Error('Missing OUTPUT_DIR');
  if (!existsSync(src)) throw new Error('Source directory does not exist: ' + src);
  if (!existsSync(out)) mkdirSync(out, { recursive: true });
  globalThis._yamlToJson = { src, out };
})();

(async () => {
  const { convert } = await import('yamlocale');
  const { src, out } = globalThis._yamlToJson;
  const languagesEnv = process.env.LANGUAGES;
  const formatEnv = process.env.FORMAT;
  const options = { sourceDir: src, outputDir: out };
  if (languagesEnv) options.languages = languagesEnv.split(',');
  if (formatEnv) options.format = formatEnv;
  await convert(options);
  globalThis._yamlToJson.result = { status: 'ok' };
})();

(async () => {
  const result = globalThis._yamlToJson.result;
  if (!result) throw new Error('No result from conversion');
  console.log(JSON.stringify({ status: result.status }));
})();
